from random import randint
from math import sqrt

def moyenne(liste):
    return sum(liste) / len(liste)

def ecart_type(liste):
    m = moyenne(liste)
    return sqrt(moyenne([(x - m)**2 for x in liste]))

def moyenne_echantillon(n):
    # moyenne de n lancers d'un dé équilibré
    return moyenne([randint(1, 6) for i in range(n)])

def proportion(liste, mu, e):
    # proportion des valeurs x de la liste telles que |x - mu| <= e
    compte = 0
    for x in liste:
        if abs(x - mu) <= e:
            compte = compte + 1
    return compte / len(liste)

N = 1000                    # nombre d'échantillons
n = 100                     # taille de chaque échantillon
mu = 3.5
sigma = sqrt(35 / 12)       # écart type d'un lancer de dé
moyennes = [moyenne_echantillon(n) for j in range(N)]
s = ecart_type(moyennes)
print(s, sigma / sqrt(n))   # deux nombres proches de 0,17
for k in [1, 2, 3]:
    print(k, proportion(moyennes, mu, k * s), proportion(moyennes, mu, k * sigma / sqrt(n)))

from math import sqrt

def coef_binomial(n, k):
    # (n-k+1)(n-k+2)...n / (1*2*...*k), facteur par facteur
    c = 1
    for i in range(1, k + 1):
        c = c * (n - k + i) / i
    return c

def p_egal(n, p, k):
    # P(S = k) pour S de loi binomiale B(n ; p)
    return coef_binomial(n, k) * p**k * (1 - p)**(n - k)

def proba_ecart(n, p):
    # P(|S - np| > racine de n)
    total = 0
    for k in range(n + 1):
        if abs(k - n * p) > sqrt(n):
            total = total + p_egal(n, p, k)
    return total

print(round(proba_ecart(16, 0.5), 4))    # affiche 0.0213
print(round(proba_ecart(100, 0.5), 4))   # affiche environ 0.035
